/* Italian and English strings. T(key, ...args) fills {0}, {1}… */
export let LANG = (() => {
  try { const s = localStorage.getItem('motus1d.lang'); if (s === 'it' || s === 'en') return s; } catch (e) { /* */ }
  return (navigator.language || 'it').toLowerCase().startsWith('en') ? 'en' : 'it';
})();
export function setLang(l) { LANG = l; try { localStorage.setItem('motus1d.lang', l); } catch (e) { /* */ } document.documentElement.lang = l; }

export function T(k, ...a) {
  let s = STR[LANG][k]; if (s == null) s = STR.en[k]; if (s == null) s = k;
  return s.replace(/\{(\d)\}/g, (m, i) => (a[+i] !== undefined ? a[+i] : m));
}
export function num(v, sd = 3) {
  if (!isFinite(v)) return '–';
  if (Math.abs(v) < 1e-9) return '0';
  const a = Math.abs(v);
  let s;
  if (a >= 1e6 || a < 1e-4) s = v.toExponential(sd - 1);
  else s = String(Number(v.toPrecision(Math.max(sd, Math.floor(Math.log10(a)) + 1))));
  if (LANG === 'it') s = s.replace('.', ',');
  return s.replace('-', '−');
}
/* values on screen use a fixed number of decimals, so they do not jump around while they change */
let DEC = 2;
export function setDec(d) { DEC = d; }
export function fx(v, d = DEC) {
  if (!isFinite(v)) return '–';
  let s = v.toFixed(d);
  if (/^-0(\.0*)?$/.test(s)) s = s.slice(1);
  if (LANG === 'it') s = s.replace('.', ',');
  return s.replace('-', '−');
}
export function applyI18n(root) {
  document.documentElement.lang = LANG;
  root.querySelectorAll('[data-i18n]').forEach(e => { e.textContent = T(e.dataset.i18n); });
  root.querySelectorAll('[data-i18n-title]').forEach(e => { const t = T(e.dataset.i18nTitle); e.title = t; e.setAttribute('aria-label', t); });
  root.querySelectorAll('[data-i18n-aria]').forEach(e => { e.setAttribute('aria-label', T(e.dataset.i18nAria)); });
}

